// JavaScript (the lines of this page that drive it)
(function(){ const el = $('#kpis'); if(!el) return; const total = d3.sum(WEEK, d=>d[1]);
  const T = [['Created · 12 weeks', total, 'geniallys, 24 Aug to 15 Nov', `+${pct(WEEK[11][1]/WEEK[0][1]-1)} first to last week`, false],['Best week', 360858, 'week of 19 Oct', 'peak of the autumn', false],['Started from templates', d3.sum(CAT, d=>d[1]), 'last 90 days, named categories', `${pct(CAT[0][1]/d3.sum(CAT,d=>d[1]))} games & challenges`, false],['Presentations, Q3 vs Q2', 111250, 'created from templates in Q3', `${pct(111250/301848-1)} vs Q2 (summer)`, true]];
  el.innerHTML = T.map(([a,v,s2,c,dn])=>`<div class="kpi"><small>${a}</small><b data-v="${v}">0</b><span>${s2}</span><i class="${dn ? 'dn' : ''}">${dn ? '▼' : '▲'} ${c}</i></div>`).join('');
  const bs = $$('b', el); const run = () => bs.forEach((b,i)=>{ const o = {v:0}, to = +b.dataset.v; if(!G || RM){ b.textContent = k(to); return; } gsap.to(o, {v:to, duration:1.6 + i*.15, ease:'power3.out', onUpdate:()=>b.textContent = k(Math.round(o.v))}); });
  if(G && M) ST.create({trigger:el, start:'top 85%', once:true, onEnter:run}); else run(); })();

