// JavaScript (the lines of this page that drive it)
chart('v-tree', W=>Math.round(clamp(W*.6, 300, 480)), (svg,W,H,anim)=>{ const total = d3.sum(CAT, d=>d[1]);
  const root = d3.hierarchy({children:CAT.map(([n,v])=>({n,v}))}).sum(d=>d.v).sort((a,b)=>b.value-a.value); d3.treemap().size([W,H]).paddingInner(2).round(true)(root);
  const g = svg.selectAll('g').data(root.leaves()).join('g').attr('transform', d=>`translate(${d.x0},${d.y0})`);
  g.append('rect').attr('width', d=>d.x1-d.x0).attr('height', d=>d.y1-d.y0).attr('rx',4).attr('fill', d=>colorOf(d.data.n)).attr('data-tip', d=>`<b>${d.data.n}</b>${fmt(d.value)} · ${pct(d.value/total)}`);
  g.filter(d=>d.x1-d.x0 > 96 && d.y1-d.y0 > 44).call(t=>{ t.append('text').attr('x',10).attr('y',22).attr('font-size',13).attr('font-weight',700).attr('fill', d=>onCol(colorOf(d.data.n))).text(d=>d.data.n).attr('pointer-events','none');
  t.append('text').attr('x',10).attr('y',40).attr('font-size',12).attr('fill', d=>onCol(colorOf(d.data.n))).attr('opacity',.8).text(d=>`${k(d.value)} · ${pct(d.value/total)}`).attr('pointer-events','none'); });
  anim(gsap.timeline().from(g.nodes(), {scale:0, transformOrigin:'0 0', opacity:0, stagger:.08, ease:'power2.out'}));

