// JavaScript (the lines of this page that drive it)
chart('v-sun', W=>Math.round(clamp(W*.7, 300, 520)), (svg,W,H,anim)=>{ const R = Math.min(W, H)/2 - 6;
  const root = d3.hierarchy({children:QS.map(([n,v])=>({n, children:v.map((x,i)=>({n:Q[i], v:x, p:n}))}))}).sum(d=>d.v||0).sort((a,b)=>b.value-a.value);
  d3.partition().size([2*Math.PI, R])(root); const nodes = root.descendants().filter(d=>d.depth);
  const arc = d3.arc().startAngle(d=>d.x0).endAngle(d=>d.x1).innerRadius(d=>d.depth === 1 ? R*.32 : R*.66).outerRadius(d=>d.depth === 1 ? R*.64 : R).padAngle(.006).cornerRadius(3);
  const g = svg.append('g').attr('transform', `translate(${W/2},${H/2})`);
  const paths = g.selectAll('path').data(nodes).join('path').attr('fill', d=>colorOf(d.depth === 1 ? d.data.n : d.data.p)).attr('fill-opacity', d=>d.depth === 1 ? 1 : .55 + d.parent.children.indexOf(d)*.1)
  .attr('data-tip', d=>d.depth === 1 ? `<b>${d.data.n}</b>${fmt(d.value)} in 5 quarters` : `<b>${d.data.p} · ${d.data.n}</b>${fmt(d.value)}`);
  g.append('text').attr('text-anchor','middle').attr('dy','-.2em').attr('font-size',26).attr('font-weight',800).attr('fill',INK).attr('font-family','Unbounded').text(k(root.value));
  g.append('text').attr('text-anchor','middle').attr('dy','1.4em').attr('font-size',12).attr('fill',MUTED).text('created from templates');
  const o = {p:0}; const draw = () => paths.attr('d', d=>{ const th = 2*Math.PI*(d.depth === 1 ? clamp(o.p*1.6) : clamp(o.p*1.6 - .6)); return th <= d.x0 ? null : arc({...d, x1: Math.min(d.x1, th)}); });
  draw(); anim(gsap.timeline().to(o, {p:1, ease:'none', onUpdate:draw}), {end:'bottom 45%'});

