  const rl = svg.append('g').selectAll('text').data(right).join('text').attr('x', Rr + 10).attr('y', d=>d.y + 4).attr('font-size', 12).attr('fill', INK).text(d=>`${sm ? d.n.split(' ')[0] : d.n} ${k(d.v)} (${pct(d.ch)})`);
