.snake .node{position:absolute;width:22px;height:22px;margin:-11px;border-radius:50%;background:#121212;border:3px solid var(--muted);transition:background-color .4s,border-color .4s}
.snake .ms.on .node{background:var(--lime);border-color:var(--lime)}
.snake .mcard{position:absolute;width:min(300px,62vw);translate:0 -50%;background:#1A1726;border-radius:18px;padding:14px 16px;opacity:.35;transition:opacity .5s,transform .5s;pointer-events:auto}

// JavaScript (the lines of this page that drive it)
const hz = $('#stHz');
$('#stHzPrev').addEventListener('click', ()=>step(-1)); $('#stHzNext').addEventListener('click', ()=>step(1));

/* CSS */
.hz .track{display:flex;gap:18px;padding:30px 20px;width:max-content}

// JavaScript (the lines of this page that drive it)
const cn = $('#stCnt');
if(cn){ const n = $('#stCntN'), bar = $('#stCntBar'), TO = 30000000, f = new Intl.NumberFormat('en'); const set = p => { n.textContent = f.format(Math.round(TO*p/1000)*1000) + (p >= 1 ? '+' : ''); bar.style.transform = `scaleX(${p})`; };
  if(G && M) ST.create({trigger:cn, pin:true, start:'top top', end:'+=150%', scrub:.4, onUpdate:s=>set(s.progress)}); else set(1); }

/* CSS */
.cnt .cbar{margin-top:34px}
.cnt{height:100svh;display:grid;place-items:center;text-align:center;background:var(--wall);color:#fff}
.cnt b{display:block;font:900 clamp(64px,16vw,220px)/.9 var(--display);letter-spacing:-.06em;font-variant-numeric:tabular-nums}
.cnt .cbar{width:min(520px,80vw);height:10px;border-radius:5px;background:rgba(255,255,255,.2);margin:20px auto 0;overflow:hidden}.cnt .cbar i{display:block;height:100%;background:var(--lime);transform-origin:0 50%}

// JavaScript (the lines of this page that drive it)
const cd = $('#stChip');

/* CSS */
.sortx .chip{min-height:44px;border:0;border-radius:999px;padding:0 16px;font:600 14px var(--body);background:#F9F8FC;color:#121212;cursor:grab;touch-action:none}
.sortx .chip[aria-pressed="true"]{outline:3px solid var(--lime);outline-offset:2px}
.sortx .chip.ok{background:var(--lime)}.sortx .chip.no{background:var(--coral);color:#fff}
.demo.d3step,.demo.chipdemo,.demo.stack2,.demo.flowbands{overflow:clip}
.chipdemo{position:relative}
.chipdemo .chip{position:-webkit-sticky;position:sticky;top:112px;z-index:3;display:inline-flex;margin:0 20px;background:#F9F8FC;color:#121212;border-radius:999px;padding:8px 14px;font:600 13px var(--mono)}

// JavaScript (the lines of this page that drive it)
const sfx = $('#storyfx');

/* CSS */
.storyfx{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:16px}
.sfx{background:#121212;border-radius:18px;overflow:hidden;display:grid;text-decoration:none;color:var(--cream)}
.sfx video{width:100%;aspect-ratio:16/10;object-fit:cover;background:#1E3BD8;display:block}
.sfx .t{padding:12px 14px;display:grid;gap:4px}
.sfx .t b{font:600 16px var(--body)}
.sfx .t span{font-size:13.5px;color:var(--muted)}
